      "source": "castSealed(caster: Actor, inst: SkillInstance): CastSealSpec | null {\n    const seal = this.zone.castSeal;\n    if (!seal) return null;\n    return castSealShuts(seal, { world: this, caster, inst, seated: this.seatOf(caster) !== undefined })\n      ? seal : null;\n  }",
