      "source": "private plantSpiritTotem(caster: Actor, inst: SkillInstance, aim: Vec2): void {\n    const def = inst.def;\n    this.spawnConstruct(caster, inst, {\n      type: 'construct', kind: 'totem',\n      range: def.ai?.range ?? 420,\n      duration: 8, maxActive: 1, life: 45, placeRange: 90,\n    }, aim, inst);\n  }",
      "sourceSha256": "0f347ef568f4d02faf6aac7dd7aea5dbe0320a1137d4f777fccf410a33791d22",
      "output": "export function scenePlantSpiritTotem(nativeHost: NativeSceneCombatHost, caster: Actor, inst: SkillInstance, aim: Vec2): void {\n    const def = inst.def;\n    nativeHost.spawnConstruct(caster, inst, {\n      type: 'construct', kind: 'totem',\n      range: def.ai?.range ?? 420,\n      duration: 8, maxActive: 1, life: 45, placeRange: 90,\n    }, aim, inst);\n  }",
