      "source": "aiNeedsFireLine(caster: Actor, inst: SkillInstance): boolean {\n    return !!LOS_CFG.aiHoldFire[inst.def.delivery.type]\n      && this.skillOcclusion(caster, inst) === 'blocked';\n  }",
      "sourceSha256": "eeb9b42045bbe5db591793f98743a562755ba05ccf31d3d5aa011e12d918ad86",
      "output": "export function sceneAiNeedsFireLine(nativeHost: NativeSceneCombatHost, caster: Actor, inst: SkillInstance): boolean {\n    return !!LOS_CFG.aiHoldFire[inst.def.delivery.type]\n      && nativeHost.skillOcclusion(caster, inst) === 'blocked';\n  }",
