      "source": "removeCorpse(c: Corpse): void {\n    const i = this.corpses.indexOf(c);\n    if (i !== -1) this.corpses.splice(i, 1);\n    // THE DEADWAKE: a CONSUMED corpse (raise-spectre / revive) feeds the tide — a\n    // heavier tick when an undead corpse is the one devoured. No-op until armed.\n    this.sim.deadwakeField?.accrue('corpse', isDeathAligned(MONSTERS[c.defId]?.faction));\n  }",
      "sourceSha256": "b4c553ba250531341020a234e151c6233b1ace82fc035199ed11e7a2575afa95",
      "output": "export function sceneRemoveCorpse(nativeHost: NativeSceneCombatHost, c: Corpse): void {\n    const i = nativeHost.corpses.indexOf(c);\n    if (i !== -1) nativeHost.corpses.splice(i, 1);\n    // THE DEADWAKE: a CONSUMED corpse (raise-spectre / revive) feeds the tide — a\n    // heavier tick when an undead corpse is the one devoured. No-op until armed.\n    nativeHost.sim.deadwakeField?.accrue('corpse', isDeathAligned(MONSTERS[c.defId]?.faction));\n  }",
