      "source": "private throngRecruitCap(keeper: Actor, inst: SkillInstance): number {\n    const evo = throngEvolution(inst);\n    return Math.max(evo.minimum ?? 0, evo.overflowCap ?? this.throngCapOf(keeper, inst));\n  }",
