      "output": "export function sceneHivecallPayload(nativeHost: NativeSceneCombatHost, caster: Actor, host: SkillInstance, id: string): void {\n    const payload = makeSkillInstance(SKILLS[id], effectiveSkillLevel(host));\n    nativeHost.executeSkill(caster, payload, { ...caster.pos });\n  }",
      "outputSha256": "b97de1047601eb62f988350ffaf88883d0247e7e911ebf92d4f1e101b11b0003",
