      "source": "throngBodiesOf(keeper: Actor, skillId: string): Actor[] {\n    const marker = throngMarkerOf(skillId);\n    return this.actors.filter(a =>\n      !a.dead && a.owner === keeper && a.sourceSkillId === marker);\n  }",
