      "group": "Resolution",
      "line": 35792,
      "source": "addTempGround(pos: Vec2, kind: string, radius: number, duration: number,\n    opts?: { shallow?: boolean; evaporate?: { rate?: number } }): void {\n    const doodad: Doodad = {\n      pos: vec(pos.x, pos.y), radius, kind,\n      ...(opts?.shallow ? { shallow: true } : {}),\n    };\n    this.doodads.push(doodad);\n    this.grounds.push(doodad);\n    this.tempGrounds.push({\n      doodad, remaining: duration,\n      ...(opts?.evaporate\n        ? { evaporate: { rate: opts.evaporate.rate ?? CREEP_CFG.front.fadeRate } }\n        : {}),\n    });\n  }",
      "sourceSha256": "38cfe5e0108194fa27e654f528bb3fd2b9708a236772994e6af557840dcb74af",
      "output": "export function sceneAddTempGround(nativeHost: NativeSceneCombatHost, pos: Vec2, kind: string, radius: number, duration: number,\n    opts?: { shallow?: boolean; evaporate?: { rate?: number } }): void {\n    const doodad: Doodad = {\n      pos: vec(pos.x, pos.y), radius, kind,\n      ...(opts?.shallow ? { shallow: true } : {}),\n    };\n    nativeHost.doodads.push(doodad);\n    nativeHost.grounds.push(doodad);\n    nativeHost.tempGrounds.push({\n      doodad, remaining: duration,\n      ...(opts?.evaporate\n        ? { evaporate: { rate: opts.evaporate.rate ?? CREEP_CFG.front.fadeRate } }\n        : {}),\n    });\n  }",
